const car='biler <- mtcars';
const ola=(year,topic,title,prompt,solution,{level=1,setup=car,packages=[],hint='Læs dataene først, og byg løsningen trin for trin.',explanation='Opgaven træner en kodeidé fra OLA-materialet med et lille, lokalt datasæt.',source=''}={})=>({id:`ola${year}-${title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,olaYear:String(year),topic,title,prompt,solution,setup,packages,kind:'code',level,starter:'# Skriv din løsning her\n',hint,explanation,source});

export const olaExercises=[
 ola(2,'frames','Rens bydata med to betingelser','BYdata indeholder både byer og rækkerne "Uden fast bopæl". Returnér kun byer med mindst 500 indbyggere. Behold alle kolonner.','BYdata[!grepl("Uden fast bopæl", BYdata$BYER) & BYdata$value >= 500, ]',{setup:'BYdata <- data.frame(BYER = c("Aarhus", "Uden fast bopæl", "Odense", "Landsby"), value = c(290000, 0, 180000, 420))',source:'OLA2GRP4-main',hint:'Kombinér betingelserne med &, og brug grepl() til at finde teksten.'}),
 ola(2,'frames','Lav bykategorier med case_when','Brug dplyr::mutate() og case_when() til at oprette kolonnen bykategori. value mindst 200000 betyder "Stor", mindst 20000 betyder "Mellem", ellers "Lille". Returnér hele datasættet.','byer |> mutate(bykategori = case_when(value >= 200000 ~ "Stor", value >= 20000 ~ "Mellem", TRUE ~ "Lille"))',{level:2,setup:'byer <- data.frame(by = c("A", "B", "C"), value = c(250000, 45000, 9000))',packages:['dplyr'],source:'OLA2GRP4-main',hint:'Sæt den højeste grænse først. TRUE ~ ... håndterer alle resterende rækker.'}),
 ola(2,'frames','Rens priser til tal','Kolonnen pris indeholder tekster med kr., punktummer og mellemrum. Fjern alt andet end cifre og konvertér resultatet til numeriske værdier. Returnér vektoren.','as.numeric(gsub("[^0-9]", "", boliger$pris))',{level:2,setup:'boliger <- data.frame(pris = c("1.250.000 kr.", "875 000 kr.", "2.100.000 kr."))',source:'OLA2GRP4-main',hint:'gsub() kan erstatte alt, der ikke matcher [0-9], med tom tekst.'}),
 ola(2,'frames','Saml bytal med boligdata','Beregn ét samlet indbyggertal pr. by med aggregate(). Kombinér derefter bytal med boligdata via by-kolonnen. Returnér det flettede datasæt.','merge(aggregate(indbyggere ~ by, data = bytal, FUN = sum), boliger, by = "by")',{level:3,setup:'bytal <- data.frame(by = c("A", "A", "B"), indbyggere = c(100, 50, 80))\nboliger <- data.frame(by = c("A", "B"), pris = c(2000000, 1500000))',source:'OLA2GRP4-main',hint:'Lav først et datasæt med én række pr. by; merge() matcher derefter på by.'}),
 ola(2,'stats','Gennemsnitspris pr. kategori','Brug group_by() og summarise() til at beregne gennemsnitlig kvmpris for hver bykategori. Kald resultatkolonnen gennemsnit_kvmpris.','boliger |> group_by(bykategori) |> summarise(gennemsnit_kvmpris = mean(kvmpris))',{level:2,setup:'boliger <- data.frame(bykategori = c("Stor", "Stor", "Lille", "Lille"), kvmpris = c(52000, 48000, 18000, 22000))',packages:['dplyr'],source:'OLA2GRP4-main',hint:'Gruppér efter bykategori, og beregn derefter mean(kvmpris).'}),
 ola(2,'vectors','Årlig vækst fra kvartalsdata','Tilføj kolonnen Realvaekst til privatforbrug. Sammenlign hvert kvartal med samme kvartal året før med formlen (værdi / værdi fire kvartaler før - 1) * 100. De første fire værdier skal være NA.','mutate(privatforbrug, Realvaekst = (Privatforbrug / lag(Privatforbrug, 4) - 1) * 100)',{level:2,setup:'privatforbrug <- data.frame(TID = paste0("2023K", rep(1:4, 2)), Privatforbrug = c(100, 102, 105, 107, 104, 106, 110, 112))',packages:['dplyr'],source:'OLA2GRP4-main',hint:'lag(x, 4) flytter værdierne fire kvartaler tilbage.'}),
 ola(2,'frames','Saml prognoser med kvartal som nøgle','Saml DI- og DST-prognoserne med inner_join() på Tidsinterval. Behold kun kvartaler, der findes i begge datasæt.','inner_join(di, dst, by = "Tidsinterval")',{level:2,setup:'di <- data.frame(Tidsinterval = c("2025K1", "2025K2", "2025K3"), Forudsagt_DI = c(1.1, 1.4, 1.2))\ndst <- data.frame(Tidsinterval = c("2025K2", "2025K3", "2025K4"), Forudsagt_DST = c(1.3, 1.5, 1.7))',packages:['dplyr'],source:'OLA2GRP4-main',hint:'Angiv fælles nøglekolonne med by = "Tidsinterval".'}),
 ola(2,'stats','Beregn RSS og TSS','Beregn RSS som summen af residualerne i anden potens. Beregn TSS som summen af de faktiske værdiers kvadrerede afstand til deres gennemsnit. Returnér c(RSS = ..., TSS = ...).','c(RSS = sum((observationer$faktisk - observationer$forudsagt)^2), TSS = sum((observationer$faktisk - mean(observationer$faktisk))^2))',{level:2,setup:'observationer <- data.frame(faktisk = c(1, 3, 4, 6), forudsagt = c(1.5, 2.5, 3.5, 5))',source:'OLA2GRP4-main',hint:'Residual = faktisk minus forudsagt. TSS måler variation omkring gennemsnittet.'}),
 ola(2,'frames','Gør kvartaler til kolonner','Brug pivot_wider() til at lave én række pr. år og én kolonne pr. kvartal. Brug kolonnen value som indhold, og kald kvartalskolonnerne K1, K2 osv.','pivot_wider(forbrug, id_cols = Aar, names_from = Kvartal, values_from = value, names_prefix = "K")',{level:2,setup:'forbrug <- data.frame(Aar = c(2024, 2024, 2025, 2025), Kvartal = c(1, 2, 1, 2), value = c(100, 110, 105, 114))',packages:['tidyr'],source:'OLA2GRP4-main',hint:'id_cols angiver, hvad der identificerer en række; names_from laver kolonnenavnene.'}),
 ola(2,'functions','Brug et for-loop på flere byer','For hver by i byer skal løkken beregne gennemsnittet af dens indbyggertal og gemme tallet i en navngivet vektor gennemsnit. Returnér gennemsnit.','gennemsnit <- numeric(length(byer))\nnames(gennemsnit) <- names(byer)\nfor (i in seq_along(byer)) {\n  gennemsnit[i] <- mean(byer[[i]])\n}\ngennemsnit',{level:3,setup:'byer <- list(Aarhus = c(280000, 282000), Odense = c(180000, 181000), Aalborg = c(120000, 121000))',source:'OLA2GRP4-main',hint:'Opret først en tom vektor. Brug derefter i til at gemme hvert gennemsnit på den rette plads.'}),
 ola(2,'frames','Beregn vækst efter pivotering','forbrug_aar har kolonnerne Aar, K1, K2, K3 og K4. Tilføj Foerste_halvaar som K1 + K2 og Vaekst_halvaar som procentvis ændring fra foregående år. Returnér datasættet.','mutate(forbrug_aar, Foerste_halvaar = K1 + K2, Vaekst_halvaar = (Foerste_halvaar / lag(Foerste_halvaar) - 1) * 100)',{level:3,setup:'forbrug_aar <- data.frame(Aar = 2022:2025, K1 = c(90, 92, 95, 99), K2 = c(95, 97, 100, 104), K3 = c(98, 101, 103, 108), K4 = c(100, 102, 106, 111))',packages:['dplyr'],source:'OLA2GRP4-main',hint:'Beregn summen af K1 og K2 først; brug lag() til at hente sidste års halvår.'}),
 ola(2,'simulation','Plot gennemsnit pr. bykategori','Tegn et søjlediagram med bykategori på x-aksen og gennemsnit_kvmpris på y-aksen. Brug ggplot() og geom_col(). Lad plottet være sidste udtryk.','ggplot(plotdata, aes(x = bykategori, y = gennemsnit_kvmpris)) + geom_col()',{level:2,setup:'plotdata <- data.frame(bykategori = c("Stor", "Mellem", "Lille"), gennemsnit_kvmpris = c(52000, 34000, 21000))',packages:['ggplot2'],source:'OLA2GRP4-main',hint:'geom_col() bruger værdierne, der allerede står i datasættet.'}),
 ola(3,'stats','Byg en regressionsformel dynamisk','Brug reformulate() til at lave formlen Realvaekst forklaret af F1 og F2. Tilpas en lineær model med lm() og returnér modellens R².','summary(lm(reformulate(c("F1", "F2"), response = "Realvaekst"), data = indikatorer))$r.squared',{level:2,setup:'indikatorer <- data.frame(Realvaekst = c(1, 2, 2, 4, 5, 6), F1 = c(4, 3, 6, 5, 8, 9), F2 = c(2, 4, 3, 6, 7, 8))',source:'OLA3-GRP4-main',hint:'reformulate() tager først en vektor med forklarende kolonner og derefter response = ... .'}),
 ola(3,'vectors','Tæl spørgsmål i indikatorer','Vektoren indeholder indikatorer som "F1, F2, F3". Del hver tekst ved komma-mellemrum, tæl hvor tit hvert spørgsmål forekommer, og sortér fra hyppigst til mindst hyppigst.','sort(table(unlist(strsplit(indikatorer, ", ", fixed = TRUE))), decreasing = TRUE)',{level:3,setup:'indikatorer <- c("F1, F2, F3", "F2, F4", "F1, F2", "F3, F4")',source:'OLA3-GRP4-main',hint:'strsplit() laver lister; unlist() samler delene, så table() kan tælle dem.'}),
 ola(3,'frames','Saml måneder til kvartaler','Månedsdata indeholder TID i formatet YYYY-MM og value. Opret år og kvartal ud fra TID, og beregn gennemsnit pr. kvartal. Returnér kolonnerne Aar, Kvartal og value.','aggregate(value ~ Aar + Kvartal, data = transform(maneder, Aar = substr(TID, 1, 4), Kvartal = paste0(substr(TID, 1, 4), "K", ceiling(as.numeric(substr(TID, 6, 7)) / 3))), FUN = mean)',{level:2,setup:'maneder <- data.frame(TID = c("2025-01", "2025-02", "2025-03", "2025-04", "2025-05", "2025-06"), value = c(10, 12, 11, 13, 15, 14))',source:'OLA3-GRP4-main',hint:'Kvartal beregnes som ceiling(måned / 3). aggregate() beregner ét gennemsnit pr. år og kvartal.'}),
 ola(3,'functions','Stabilitet med indlejrede løkker','Beregn R² for F1 og F2 i hver af de to perioder. Gem tallene i en matrix med rækkerne F1, F2 og kolonnerne P1, P2. Brug en for-løkke i begge dimensioner.','r2 <- matrix(NA_real_, nrow = 2, ncol = 2, dimnames = list(c("F1", "F2"), c("P1", "P2")))\nfor (p in 1:2) {\n  data_periode <- perioder[[p]]\n  for (i in 1:2) {\n    model <- lm(data_periode$Realvaekst ~ data_periode[[c("F1", "F2")[i]]])\n    r2[i, p] <- summary(model)$r.squared\n  }\n}\nr2',{level:3,setup:'perioder <- list(P1 = data.frame(Realvaekst = c(1, 2, 3, 5, 6), F1 = c(2, 3, 4, 6, 7), F2 = c(5, 4, 6, 3, 5)), P2 = data.frame(Realvaekst = c(2, 3, 5, 6, 8), F1 = c(1, 3, 4, 6, 9), F2 = c(2, 5, 4, 8, 7)) )',source:'OLA3-GRP4-main',hint:'Den ydre løkke vælger periode; den indre løkke vælger indikator. Gem R² på r2[i, p].'}),
 ola(3,'stats','Multipel regression uden manglende rækker','Datasættet har manglende værdier. Tilpas en multipel lineær regression med Realvaekst som respons og alle øvrige kolonner som forklarende variable. Fjern rækker med NA før modellen tilpasses. Returnér modellen.','lm(Realvaekst ~ ., data = na.omit(multipel_data))',{level:2,setup:'multipel_data <- data.frame(Realvaekst = c(1, 3, 2, 5, 4, 7), F1 = c(2, 4, NA, 5, 6, 8), F2 = c(3, 2, 4, 5, NA, 7))',source:'OLA3-GRP4-main',hint:'na.omit() fjerner rækker med manglende værdier, før lm() bruger dem.'}),
 ola(3,'frames','Forbind modelresultater med kvartal','Saml resultat_DI og resultat_DST via inner_join() med Tidsinterval som nøgle. Behold kun fælles kvartaler.','inner_join(resultat_DI, resultat_DST, by = "Tidsinterval")',{level:2,setup:'resultat_DI <- data.frame(Tidsinterval = c("2024K1", "2024K2", "2024K3"), Faktisk = c(1, 2, 3), Forudsagt_DI = c(1.2, 1.8, 3.2))\nresultat_DST <- data.frame(Tidsinterval = c("2024K2", "2024K3", "2024K4"), Forudsagt_DST = c(2.1, 2.9, 3.8))',packages:['dplyr'],source:'OLA3-GRP4-main',hint:'inner_join() beholder kun fælles nøgler.'}),
 ola(3,'functions','Beregn gennemsnit i rullende vinduer','Brug en for-løkke til at beregne gennemsnittet af de seneste tre værdier i hver position. For x med længde 6 skal resultatet have længde 4.','rullende <- numeric(length(x) - 2)\nfor (i in seq_along(rullende)) {\n  rullende[i] <- mean(x[i:(i + 2)])\n}\nrullende',{level:2,setup:'x <- c(8, 10, 12, 11, 15, 18)',source:'OLA3-GRP4-main',hint:'For hver startposition i tager du tre værdier: x[i:(i + 2)].'}),
 ola(3,'frames','Læs egenskaber ud af JSON','JSON-teksten indeholder en liste af observationer. Brug jsonlite::fromJSON() med flatten = TRUE og returnér observationerne som et data frame.','as.data.frame(fromJSON(observationer_json, flatten = TRUE))',{level:2,setup:'observationer_json <- \'[{"properties":{"station":"A","wind_speed":12.5}},{"properties":{"station":"B","wind_speed":14.2}}]\'',packages:['jsonlite'],source:'OLA3-GRP4-main',hint:'flatten = TRUE gør indlejrede felter til kolonner; as.data.frame() sikrer data frame-format.'})
];


const olaReferences=[["Rens bydata med to betingelser","1.1","OPG1.1"],["Lav bykategorier med case_when","1.2","OPG1.2"],["Rens priser til tal","1.3","OPG1.3"],["Saml bytal med boligdata","1.3","OPG1.3"],["Gennemsnitspris pr. kategori","1.4","OPG1.4"],["Årlig vækst fra kvartalsdata","2.1","OPG2.1 REVIDERET"],["Saml prognoser med kvartal som nøgle","3.1","OPG3.1"],["Beregn RSS og TSS","3.3","OPG3.3"],["Gør kvartaler til kolonner","4.3","OPG4.3"],["Brug et for-loop på flere byer","4.4","OPG4.4"],["Beregn vækst efter pivotering","5.1","OPG5.1"],["Plot gennemsnit pr. bykategori","1.4","OPG1.4"],["Byg en regressionsformel dynamisk","1.2","Opgave 1.2.r"],["Tæl spørgsmål i indikatorer","1.3","Opgave 1.3.r"],["Saml måneder til kvartaler","1.4","Opgave 1.4.r"],["Stabilitet med indlejrede løkker","4.1","Opgave 4.1.r"],["Multipel regression uden manglende rækker","2.1","Opgave 2.1.r"],["Forbind modelresultater med kvartal","3.1 og 3.2","Opgave 3.1 og 3.2.r"],["Beregn gennemsnit i rullende vinduer","4.1","opg4 rul"],["Læs egenskaber ud af JSON","5.2","Opgave 5.2.r"]];
for(const exercise of olaExercises){const reference=olaReferences.find(([title])=>title===exercise.title);if(!reference)throw new Error('Mangler OLA-kildereference: '+exercise.title);exercise.olaSubtask=reference[1];exercise.olaTask=reference[1].split('.')[0];exercise.sourceFile=reference[2];}

export const olaYears=[
 {id:'1',label:'OLA 1',available:false,description:'Plads reserveret til senere OLA 1-træning.'},
 {id:'2',label:'OLA 2',available:true,description:'BY-data, boligpriser, prognoser, regression og visualisering.'},
 {id:'3',label:'OLA 3',available:true,description:'Indikatorer, regression, løkker, stabilitet, JSON og API-data.'},
 {id:'4',label:'OLA 4',available:false,description:'Plads reserveret til senere OLA 4-træning.'},
 {id:'5',label:'OLA 5',available:false,description:'Plads reserveret til senere OLA 5-træning.'}
];

export function normalizeOlaYears(value){return ['2','3'].filter(year=>Array.isArray(value)&&value.includes(year));}
